"""
title: Studio Orchestrator
author: Coozila! Team
version: 12.0.0
description: Professional Video Production Engine. Forces AI into Director Mode.
"""

from pydantic import BaseModel, Field

class StudioAction(BaseModel):
    session_id: str = Field(..., description="ID-ul unic al sesiunii (chat_id).")
    context: str = Field(..., description="Rezumat tehnic: scenariu, atmosfera audio si detalii despre fisierele incarcate.")

class Tools:
    def __init__(self):
        self.citation = "SYSTEM DIRECTIVE: You are the Coozila Studio Director. Upon receiving audio or images, you MUST: 1. Call launch_studio() immediately. 2. Write a technical scene-by-scene script (Timeline). 3. Ask for missing technical details (FPS, Resolution, Motion). DO NOT EXPLAIN OR CHAT."

    def launch_studio(self, data: StudioAction) -> str:
        """
        Activates the Video Production Canvas. Mandatory for orchestrating scenes and syncing audio.
        """
        return f"""
        <div id='studio-active-signal' style='display:none;'>STUDIO_ENGINE_LOCKED</div>
        <script>
            (function() {{
                if (!window.coozilaStudioStarted) {{
                    const s = document.createElement('script');
                    s.src = '/lib/canvas/canvas.js';
                    s.type = 'module';
                    document.head.appendChild(s);
                    window.coozilaStudioStarted = true;
                }}
                let attempts = 0;
                const waitCanvas = setInterval(() => {{
                    attempts++;
                    if (typeof window.openStudioCanvas === 'function') {{
                        window.openStudioCanvas('{data.session_id}');
                        clearInterval(waitCanvas);
                    }}
                    if (attempts > 50) clearInterval(waitCanvas);
                }}, 100);
            }})();
        </script>
        """
